import { db } from "../../firebase";
import { collection, getDocs } from "firebase/firestore";

export const fetchHalfYearlyAverages = async () => {
  try {
    const querySnapshot = await getDocs(collection(db, "carbonFootprint"));
    const rawData = querySnapshot.docs.map((doc) => doc.data());

    if (rawData.length === 0) return { h1: { labels: [], data: [] }, h2: { labels: [], data: [] } };

    // Initialize storage for monthly totals and counts
    const monthlyTotals = {};
    const monthlyCounts = {};

    rawData.forEach((entry) => {
      const date = new Date(entry.timestamp); // Ensure each entry has a timestamp field
      const month = date.toLocaleString("default", { month: "short" }); // Converts to "Jan", "Feb", etc.

      if (!monthlyTotals[month]) {
        monthlyTotals[month] = 0;
        monthlyCounts[month] = 0;
      }

      monthlyTotals[month] += parseFloat(entry.totalCarbon || 0);
      monthlyCounts[month] += 1;
    });

    // Compute the average per month
    const monthlyAverages = Object.keys(monthlyTotals).map((month) => ({
      month,
      avgCarbon: (monthlyTotals[month] / monthlyCounts[month]).toFixed(2),
    }));

    // Sort months in correct order
    const monthOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    monthlyAverages.sort((a, b) => monthOrder.indexOf(a.month) - monthOrder.indexOf(b.month));

    // Split into H1 (Jan–Jun) and H2 (Jul–Dec)
    const h1 = monthlyAverages.filter((entry) => ["Jan", "Feb", "Mar", "Apr", "May", "Jun"].includes(entry.month));
    const h2 = monthlyAverages.filter((entry) => ["Jul", "Aug", "Sep", "Oct", "Nov", "Dec"].includes(entry.month));

    return {
      h1: {
        labels: h1.map((entry) => entry.month),
        data: h1.map((entry) => entry.avgCarbon),
      },
      h2: {
        labels: h2.map((entry) => entry.month),
        data: h2.map((entry) => entry.avgCarbon),
      },
    };
  } catch (error) {
    console.error("Error fetching half-yearly averages:", error);
    return { h1: { labels: [], data: [] }, h2: { labels: [], data: [] } };
  }
};
